133	    public GuardianWorkerCreateCapability GrantWorkerCreateCapability(
134	        WorkerCreateCapabilityRequestedEvent request,
135	        long nowUnixTimeMilliseconds,
136	        long maximumDeadlineUnixTimeMilliseconds)
137	    {
138	        ArgumentNullException.ThrowIfNull(request);
139	        if (maximumDeadlineUnixTimeMilliseconds <= nowUnixTimeMilliseconds)
140	        {
141	            throw new ArgumentOutOfRangeException(
142	                nameof(maximumDeadlineUnixTimeMilliseconds));
143	        }
144	        if (request.GuardianBootId != _guardianBootId)
145	        {
146	            throw new InvalidOperationException(
147	                "The worker create request does not match the frozen session binding.");
148	        }
149	
150	        lock (_sync)
151	        {
152	            if (!_aliases.TryGetValue(request.SessionAlias, out var state) ||
153	                request.SessionTransitionVersion != state.Binding.TransitionVersion ||
154	                request.BindingDigest != state.Binding.BindingDigest ||
155	                request.StartupDeadlineUnixTimeMilliseconds <= nowUnixTimeMilliseconds ||
156	                request.StartupDeadlineUnixTimeMilliseconds >
157	                    maximumDeadlineUnixTimeMilliseconds)
158	            {
159	                throw new InvalidOperationException(
160	                    "The worker create request does not match the frozen session binding.");
161	            }
162	
163	            var token = _createCapabilityToken() ??
164	                throw new InvalidOperationException(
165	                    "The worker create capability token source returned null.");
166	            var generation = _workerGenerations.Allocate(request.SessionAlias);
167	            state.HighWatermark = new WorkerGenerationHighWatermarkEntry(
168	                request.SessionAlias,
169	                new WorkerGenerationHighWatermark(generation.Value));
170	            state.PendingWorkerGeneration = generation;
171	            state.State = PublicSessionState.Starting;
172	            state.ReadyForEffects = false;
173	            state.BootstrapState = BootstrapState.Pending;
174	            // Starting is a manual state, so the public contract forbids it
175	            // carrying recovery facts. A worker create issued while automatic
176	            // recovery is in flight would otherwise leave the previous
177	            // recovering event's phase attached to a Starting alias, and every
178	            // subsequent snapshot - so every ptk_state and ptk_session list -
179	            // would throw instead of answering. The host re-announces recovery
180	            // on its own lifecycle events when it wants those states projected.
181	            ClearRecoveryMetadata(state);
182	            return new GuardianWorkerCreateCapability(generation, token);
183	        }
184	    }
