222	    private static PublicSessionStateSnapshot ProjectSession(AliasState state)
223	    {
224	        // While recovery is in flight the alias's bound identity is the dead
225	        // generation, so report exactly the worker the host named for this
226	        // recovery and nothing else. A cold alias has no worker at all.
227	        var projectedWorker = state.State == PublicSessionState.Cold
228	            ? null
229	            : SessionLifecycleEvent.CarriesRecoveryMetadata(state.State)
230	                ? state.RecoveringWorkerIdentity
231	                : state.WorkerIdentity;
