668	        /// dispatch target, never reconstructed afterwards. It is what lets a
669	        /// stale dispatch be refused as retryable backend_lost_before_dispatch
670	        /// carrying real recovery metadata, instead of the blanket nonretryable
671	        /// recovery_unknown the supervisor falls back to without it.
672	        /// </summary>
673	        internal GuardianHostJobListTargetInvalidation? Invalidation { get; set; }
