675	        /// <summary>
676	        /// True while a session-changing request's outcome is unknown and no
677	        /// authoritative result has repaired the alias. It is sticky on purpose:
678	        /// a host restoring its declared session must not clear it, or the
679	        /// ambiguity is erased and ordinary work can be dispatched into a
680	        /// session whose outcome nobody knows. Only
681	        /// <see cref="ObserveSessionOperationResult"/> clears it.
682	        /// </summary>
683	        internal bool AmbiguousUntilRepaired { get; set; }
