    97	public sealed record PublicSessionStateSnapshot
    98	{
    99	    /// <summary>
   100	    /// The one canonical session state/recovery-phase pairing. Every producer of
   101	    /// a session recovery fact — the public snapshot and the guardian/host
   102	    /// lifecycle event that carries the fact across the private pipe — validates
   103	    /// against this rule, so a wire fact the host can emit is always a fact the
   104	    /// guardian can project.
   105	    /// </summary>
   106	    public static void ValidateRecoveryPhasePairing(
   107	        PublicSessionState state,
   108	        RecoveryPhase? recoveryPhase)
   109	    {
   110	        var expectedPhase = state switch
   111	        {
   112	            PublicSessionState.Backoff => global::PtkSharedContracts.RecoveryPhase.Backoff,
   113	            PublicSessionState.Bootstrapping => global::PtkSharedContracts.RecoveryPhase.Bootstrap,
   114	            PublicSessionState.CircuitOpen => global::PtkSharedContracts.RecoveryPhase.CircuitOpen,
   115	            PublicSessionState.HalfOpen => global::PtkSharedContracts.RecoveryPhase.HalfOpen,
   116	            _ => (RecoveryPhase?)null,
   117	        };
   118	        if (expectedPhase is not null && recoveryPhase != expectedPhase)
   119	            throw new ArgumentException("Session recovery phase does not match its state.");
   120	        if (state == PublicSessionState.Recovering && recoveryPhase is not (
   121	                global::PtkSharedContracts.RecoveryPhase.Containment or
   122	                global::PtkSharedContracts.RecoveryPhase.Attempting))
   123	            throw new ArgumentException("Recovering session has an invalid phase.");
   124	        var manual = state is PublicSessionState.Cold or PublicSessionState.Starting or
   125	            PublicSessionState.Ready or PublicSessionState.Resetting or PublicSessionState.Closing or
   126	            PublicSessionState.Faulted or PublicSessionState.Lost or PublicSessionState.Quarantined or
   127	            PublicSessionState.RecoveryUnknown;
   128	        if (manual && recoveryPhase is not null)
   129	            throw new ArgumentException("Nonautomatic session state cannot carry a recovery phase.");
   130	    }
