   226	        {
   227	            writer.WriteStartObject();
   228	            writer.WriteString("schema_version", snapshot.SchemaVersion);
   229	            writer.WriteString("guardian_boot_id", snapshot.GuardianBootId.ToString());
   230	            writer.WritePropertyName("host");
