   392	        ? null
   393	        : ParseCanonicalUuidV4(value.ValueKind == JsonValueKind.String
   394	            ? value.GetString()!
   395	            : throw new InvalidDataException("Expected nullable UUIDv4."), "UUIDv4");
   396	    private static long RequiredLong(JsonElement root, string name) => root.GetProperty(name).TryGetInt64(out var value) ? value : throw new InvalidDataException();
