   402	    private static Guid ParseCanonicalUuidV4(string text, string name)
   403	    {
   404	        if (!Guid.TryParseExact(text, "D", out var parsed) ||
   405	            !string.Equals(text, parsed.ToString("D"), StringComparison.Ordinal) ||
   406	            text[14] != '4' || text[19] is not ('8' or '9' or 'a' or 'b'))
   407	            throw new InvalidDataException($"'{name}' must be a lowercase canonical UUIDv4.");
   408	        return parsed;
   409	    }
