332	    public void ObserveSessionLifecycle(
333	        SessionLifecycleEvent lifecycleEvent)
334	    {
335	        ArgumentNullException.ThrowIfNull(lifecycleEvent);
336	        if (lifecycleEvent.GuardianBootId != _guardianBootId)
337	        {
338	            throw new InvalidOperationException(
339	                "The session lifecycle event does not match the frozen binding.");
340	        }
341	
342	        lock (_sync)
343	        {
344	            if (!_aliases.TryGetValue(lifecycleEvent.SessionAlias, out var state) ||
345	                lifecycleEvent.SessionTransitionVersion !=
346	                    state.Binding.TransitionVersion)
347	            {
348	                throw new InvalidOperationException(
349	                    "The session lifecycle event does not match the frozen binding.");
350	            }
351	
352	            if (lifecycleEvent.State == PublicSessionState.Ready)
353	            {
354	                var worker = lifecycleEvent.WorkerIdentity ??
355	                    throw new InvalidOperationException(
356	                        "A ready session lifecycle event requires a worker.");
357	                if (state.PendingWorkerGeneration is null ||
358	                    worker.Generation != state.PendingWorkerGeneration ||
359	                    !lifecycleEvent.ReadyForEffects ||
360	                    lifecycleEvent.BootstrapState != BootstrapState.Restored)
361	                {
362	                    throw new InvalidOperationException(
363	                        "The ready lifecycle event does not match the pending worker grant.");
364	                }
365	                state.WorkerIdentity = worker;
366	                state.AuditSession = new GuardianAuditSession(
367	                    state.Binding,
368	                    worker.Generation);
369	                state.PendingWorkerGeneration = null;
370	            }
371	            else if (lifecycleEvent.State == PublicSessionState.Cold)
372	            {
373	                if (lifecycleEvent.WorkerIdentity is not null ||
374	                    lifecycleEvent.ReadyForEffects ||
375	                    lifecycleEvent.BootstrapState !=
376	                        BootstrapState.NotApplicable)
377	                {
378	                    throw new InvalidOperationException(
379	                        "The cold lifecycle event carries live worker state.");
380	                }
381	                state.PendingWorkerGeneration = null;
382	            }
383	            else if (lifecycleEvent.State == PublicSessionState.Faulted)
384	            {
385	                var faultWorker = lifecycleEvent.WorkerIdentity ??
386	                    throw new InvalidOperationException(
387	                        "A faulted session lifecycle event requires a worker.");
388	                if (faultWorker.BootId != state.WorkerIdentity.BootId ||
389	                    faultWorker.Generation != state.WorkerIdentity.Generation ||
390	                    lifecycleEvent.ReadyForEffects ||
391	                    lifecycleEvent.BootstrapState != BootstrapState.Failed ||
392	                    lifecycleEvent.Reason is not (
393	                        GuardianHostSessionLifecycleReason.ContainmentUnconfirmed or
394	                        GuardianHostSessionLifecycleReason.BootstrapFailed or
395	                        GuardianHostSessionLifecycleReason.CircuitTransition))
396	                {
397	                    throw new InvalidOperationException(
398	                        "The faulted lifecycle event does not match the current worker or reason.");
399	                }
400	                state.PendingWorkerGeneration = null;
401	            }
402	            else if (SessionLifecycleEvent.CarriesRecoveryMetadata(lifecycleEvent.State))
403	            {
404	                // Automatic recovery in flight for this alias. The event names a
405	                // worker only where the wire contract requires one, so validate
406	                // the identity when present rather than demanding it: it is
407	                // either the worker whose loss started recovery, or the pending
408	                // grant being bootstrapped. The identity is deliberately NOT
409	                // absorbed here — recovery has produced no bound worker yet, and
410	                // only the Ready branch's grant match may rebind the alias.
411	                if (lifecycleEvent.WorkerIdentity is { } recoveringWorker)
412	                {
413	                    var namesCurrentWorker =
414	                        recoveringWorker.BootId == state.WorkerIdentity.BootId &&
415	                        recoveringWorker.Generation == state.WorkerIdentity.Generation;
416	                    var namesPendingGrant =
417	                        state.PendingWorkerGeneration is { } pendingGeneration &&
418	                        recoveringWorker.Generation == pendingGeneration;
419	                    if (!namesCurrentWorker && !namesPendingGrant)
420	                    {
421	                        throw new InvalidOperationException(
422	                            "The recovering lifecycle event names an unknown worker.");
423	                    }
424	                }
425	                if (lifecycleEvent.ReadyForEffects)
426	                {
427	                    throw new InvalidOperationException(
428	                        "A recovering session cannot be ready for effects.");
429	                }
430	            }
431	            else
432	            {
433	                throw new InvalidOperationException(
434	                    "The frozen session received a nonterminal lifecycle event.");
435	            }
436	
437	            if (state.AmbiguousUntilRepaired &&
438	                (lifecycleEvent.State == PublicSessionState.Ready ||
439	                    SessionLifecycleEvent.CarriesRecoveryMetadata(lifecycleEvent.State)))
440	            {
441	                // Neither a host restoring its declared session nor an automatic
442	                // recovery is the explicit repair this alias is waiting for. The
443	                // worker identity above is absorbed deliberately, so a later
444	                // authoritative repair targets the live worker; the projection
445	                // stays unusable. Committing the Ready event here would silently
446	                // erase the ambiguous outcome of the earlier session-changing
447	                // request and let ordinary work be dispatched into a session
448	                // whose outcome is unknown, which is exactly the no-replay
449	                // boundary this state exists to hold. A recovering event is
450	                // refused for the same reason in the other direction: it would
451	                // downgrade a nonretryable recovery_unknown to a retryable
452	                // session_recovering and invite the model to resubmit work whose
453	                // first outcome nobody knows.
454	                state.State = PublicSessionState.RecoveryUnknown;
455	                state.ReadyForEffects = false;
456	                state.WarmStateLost = true;
457	                state.BootstrapState = BootstrapState.Unknown;
458	                ClearRecoveryMetadata(state);
459	                return;
460	            }
461	
462	            // Capture the exact target this transition invalidates, atomically
463	            // with the transition itself. The interface forbids rebuilding these
464	            // facts from a later target, so it is captured here or never.
465	            var invalidatedTarget =
466	                state.ReadyForEffects &&
467	                SessionLifecycleEvent.CarriesRecoveryMetadata(lifecycleEvent.State)
468	                    ? new GuardianHostJobListTarget(
469	                        state.Binding.Alias,
470	                        state.Binding.TransitionVersion,
471	                        state.WorkerIdentity,
472	                        state.AuditSession,
473	                        state.ReadyForEffects)
474	                    : null;
475	
476	            state.State = lifecycleEvent.State;
477	            state.ReadyForEffects = lifecycleEvent.ReadyForEffects;
478	            state.WarmStateLost |= lifecycleEvent.WarmStateLost;
479	            state.BootstrapState = lifecycleEvent.BootstrapState;
480	            // Recovery facts are carried verbatim, and every state that cannot
481	            // hold them clears them: the wire contract already guarantees the
482	            // event's metadata is null for exactly those states.
483	            state.RecoveryPhase = lifecycleEvent.RecoveryPhase;
484	            state.RecoveryAttempt = lifecycleEvent.RecoveryAttempt ?? 0;
485	            state.RetryAfterMilliseconds = lifecycleEvent.RetryAfterMilliseconds;
486	            state.RecoveringWorkerIdentity =
487	                SessionLifecycleEvent.CarriesRecoveryMetadata(lifecycleEvent.State)
488	                    ? lifecycleEvent.WorkerIdentity
489	                    : null;
490	
491	            if (invalidatedTarget is not null)
492	            {
493	                // The projection is taken after the commit, so the evidence is
494	                // this transition's own recovery snapshot rather than anything
495	                // observed later. Its constructor re-checks completeness.
496	                state.Invalidation = new GuardianHostJobListTargetInvalidation(
497	                    invalidatedTarget,
498	                    ProjectSession(state));
499	            }
500	        }
501	    }
