503	    private static void ClearRecoveryMetadata(AliasState state)
504	    {
505	        state.RecoveryPhase = null;
506	        state.RecoveryAttempt = 0;
507	        state.RetryAfterMilliseconds = null;
508	        state.RecoveringWorkerIdentity = null;
509	    }
