511	    public void ObserveSessionRecoveryUnknown(CanonicalAlias alias)
512	    {
513	        ArgumentNullException.ThrowIfNull(alias);
514	        lock (_sync)
515	        {
516	            if (!_aliases.TryGetValue(alias, out var state))
517	            {
518	                throw new InvalidOperationException(
519	                    "The ambiguous lifecycle result belongs to another session.");
520	            }
521	
